import numpy as np


def heilbronn_triangle11() -> np.ndarray:
    """Anneal, then jointly relocate the most frequent bottleneck points."""
    n = 11
    h = np.sqrt(3.0) / 2.0
    rng = np.random.default_rng(11011)
    triples = np.array(
        [(i, j, k) for i in range(n) for j in range(i + 1, n)
         for k in range(j + 1, n)], dtype=np.int32)

    def det(p):
        a, b, c = p[triples[:, 0]], p[triples[:, 1]], p[triples[:, 2]]
        return ((b[:, 0] - a[:, 0]) * (c[:, 1] - a[:, 1])
                - (b[:, 1] - a[:, 1]) * (c[:, 0] - a[:, 0]))

    def score(p):
        return float(np.min(np.abs(det(p))))

    def valid(p):
        x, y = p[:, 0], p[:, 1]
        return bool(np.all((x >= 0) & (y >= 0) &
                           (y <= np.sqrt(3.0) * x) &
                           (y <= np.sqrt(3.0) * (1.0 - x))))

    def random_points():
        u, v = rng.random(n), rng.random(n)
        m = u + v > 1.0
        u[m], v[m] = 1.0 - u[m], 1.0 - v[m]
        return np.column_stack((v + .5 * (1.0 - u - v),
                                h * (1.0 - u - v))).astype(np.float64)

    def radical(k, base):
        r, f = 0.0, 1.0 / base
        while k:
            r += (k % base) * f
            k //= base
            f /= base
        return r

    states = []
    best, best_value = None, -1.0
    for _ in range(24):
        p, value = random_points(), 0.0
        value = score(p)
        for it in range(30000):
            q = it / 30000.0
            trial = p.copy()
            trial[int(rng.integers(n))] += rng.normal(
                0.0, .16 * (1.0 - q) ** 1.7 + .001, 2)
            if not valid(trial):
                continue
            nv = score(trial)
            if nv >= value or rng.random() < np.exp(
                    (nv - value) / max(1e-9, .0025 * (1.0 - q) ** 1.25)):
                p, value = trial, nv
                if value > best_value:
                    best, best_value = p.copy(), value
        states.append((value, p.copy()))

    if best is None:
        return random_points()

    # The six strongest states undergo deterministic correlated block moves.
    try:
        from scipy.optimize import minimize
        for _, seed in sorted(states, key=lambda z: z[0], reverse=True)[:6]:
            p = seed.copy()
            for phase in range(24):
                d = det(p)
                order = np.argsort(np.abs(d))[:12]
                counts = np.bincount(triples[order].ravel(), minlength=n)
                movable = np.argsort(-counts, kind="stable")[:5]
                movable = np.sort(movable)
                signs = np.sign(d)
                signs[signs == 0] = 1.0
                old = p.copy()
                current = score(p)
                candidate = p.copy()
                candidate_value = current
                for j in range(250):
                    z = p.copy()
                    for r, idx in enumerate(movable):
                        u, v = radical(j + 1 + 251 * phase + 17 * r, 2), \
                               radical(j + 1 + 251 * phase + 17 * r, 3)
                        if u + v > 1.0:
                            u, v = 1.0 - u, 1.0 - v
                        z[idx] = (v + .5 * (1.0 - u - v),
                                  h * (1.0 - u - v))
                    zv = score(z)
                    if valid(z) and zv > candidate_value:
                        candidate, candidate_value = z, zv

                m = len(movable)
                y0 = np.concatenate((candidate[movable].ravel(),
                                     [candidate_value * .999]))
                def unpack(z):
                    q = candidate.copy()
                    for r, idx in enumerate(movable):
                        u, v = z[2*r:2*r+2]
                        q[idx] = (v + .5 * (1.0 - u - v),
                                  h * (1.0 - u - v))
                    return q

                def cons(z):
                    q = unpack(z)
                    x, y = q[:, 0], q[:, 1]
                    edge = np.concatenate((x, y, np.sqrt(3.0)*x-y,
                                           np.sqrt(3.0)*(1.0-x)-y))
                    return np.concatenate((edge, signs * det(q) - z[-1]))

                result = minimize(lambda z: -z[-1], y0, method="SLSQP",
                    bounds=[(0.0, 1.0)] * (2*m) + [(0.0, 1.0)],
                    constraints={"type": "ineq", "fun": cons},
                    options={"maxiter": 500, "ftol": 1e-11, "disp": False})
                if result.x is not None:
                    q = unpack(result.x)
                    qv = score(q)
                    if valid(q) and np.isfinite(qv) and qv > current:
                        p = q
                    else:
                        p = old
                else:
                    p = old
                if score(p) > best_value:
                    best, best_value = p.copy(), score(p)
    except Exception:
        pass
    return np.asarray(best, dtype=np.float64)
